  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn() };
});

vi.mock("../src/handoff/handoff-trigger.js", () => ({
  fireHandoffTrigger: vi.fn(),
}));

vi.mock("../src/config/workspace-config.js", () => ({
  parseManagementRepoCoords: vi.fn(() => ({
    owner: "test-owner",
    repo: "test-repo",
    baseBranch: "main",
  })),
}));

