/**
 * Slack Web API client for threaded notifications.
 *
 * Covers chat.postMessage (returns ts) and chat.update (edits an existing message by ts).
 * Requires SLACK_BOT_TOKEN from env and channel_id from workspace.yaml notifications config.
 * Returns null when Slack is not configured rather than throwing at construction time.
 */

export interface SlackPostMessageResult {
  ts: string;
  channel: string;
}

export interface SlackClientConfig {
  botToken: string;
  channelId: string;
}

const SLACK_API_BASE = "https://slack.com/api";

export class SlackWebApiClient {
  constructor(private readonly config: SlackClientConfig) {}

  async postMessage(
    text: string,
    options: { threadTs?: string; blocks?: unknown[] } = {},
  ): Promise<SlackPostMessageResult> {
    const body: Record<string, unknown> = {
      channel: this.config.channelId,
      text,
    };
    if (options.threadTs) body["thread_ts"] = options.threadTs;
    if (options.blocks) body["blocks"] = options.blocks;

    const resp = await fetch(`${SLACK_API_BASE}/chat.postMessage`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json; charset=utf-8",
        Authorization: `Bearer ${this.config.botToken}`,
      },
      body: JSON.stringify(body),
    });

    if (!resp.ok) {
      throw new Error(
        `Slack chat.postMessage HTTP error ${resp.status}: ${await resp.text()}`,
      );
    }

    const data = (await resp.json()) as Record<string, unknown>;
    if (!data["ok"]) {
      throw new Error(
        `Slack chat.postMessage returned ok=false: ${String(data["error"] ?? "unknown")}`,
      );
    }

    const ts = data["ts"];
    const channel = data["channel"];
    if (typeof ts !== "string" || !ts) {
      throw new Error("Slack chat.postMessage response missing ts field");
    }
    if (typeof channel !== "string" || !channel) {
      throw new Error("Slack chat.postMessage response missing channel field");
    }

    return { ts, channel };
  }

  async updateMessage(
    ts: string,
    text: string,
    options: { blocks?: unknown[] } = {},
  ): Promise<void> {
    const body: Record<string, unknown> = {
      channel: this.config.channelId,
      ts,
      text,
    };
    if (options.blocks) body["blocks"] = options.blocks;

    const resp = await fetch(`${SLACK_API_BASE}/chat.update`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json; charset=utf-8",
        Authorization: `Bearer ${this.config.botToken}`,
      },
      body: JSON.stringify(body),
    });

    if (!resp.ok) {
      throw new Error(
        `Slack chat.update HTTP error ${resp.status}: ${await resp.text()}`,
      );
    }

    const data = (await resp.json()) as Record<string, unknown>;
    if (!data["ok"]) {
      throw new Error(
        `Slack chat.update returned ok=false: ${String(data["error"] ?? "unknown")}`,
      );
    }
  }
}

export function createSlackWebApiClient(
  botToken: string | undefined,
  channelId: string | undefined,
): SlackWebApiClient | null {
  if (!botToken || !channelId) return null;
  return new SlackWebApiClient({ botToken, channelId });
}

