/**
 * Unit tests for post-task-slack utility.
 *
 *   1. in_review — POSTs correct Block Kit payload with PR link
 *   2. blocked   — payload includes blocked_reason section
 *   3. done      — payload has correct header and fallback text
 *   4. throws when Slack returns non-ok status
 *   5. taskTitle included in header when provided
 *   6. PR link shows "_not available_" when prUrl absent
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import { postTaskSlack } from "../src/side-effects/post-task-slack.js";

const WEBHOOK_URL = "https://hooks.slack.com/services/TEST/HOOK";
const FEATURE_ID = "my-feature";
const TASK_ID = "T3";
const PR_URL = "https://github.com/org/repo/pull/77";

afterEach(() => {
  vi.unstubAllGlobals();
});

function mockFetchOk(): ReturnType<typeof vi.fn> {
  const fn = vi.fn().mockResolvedValue({ ok: true, text: async () => "ok" });
  vi.stubGlobal("fetch", fn);
  return fn;
}

function mockFetchFail(status = 500): ReturnType<typeof vi.fn> {
  const fn = vi.fn().mockResolvedValue({
    ok: false,
    status,
    text: async () => "Internal Server Error",
  });
  vi.stubGlobal("fetch", fn);
  return fn;
}

// ── 1. in_review payload ──────────────────────────────────────────────────────

describe("postTaskSlack — in_review", () => {
  it("POSTs to the webhook with the correct payload shape", async () => {
    const mockFetch = mockFetchOk();
    await postTaskSlack({ event: "in_review", featureId: FEATURE_ID, taskId: TASK_ID, prUrl: PR_URL, webhookUrl: WEBHOOK_URL });

    expect(mockFetch).toHaveBeenCalledOnce();
    const [url, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    expect(url).toBe(WEBHOOK_URL);
    expect(init.method).toBe("POST");

    const body = JSON.parse(init.body as string) as { text: string; blocks: { type: string; text?: unknown }[] };
    expect(body.text).toContain(TASK_ID);
    expect(body.text).toContain("review");
    const header = body.blocks.find((b) => b.type === "header");
    expect(header).toBeDefined();
    expect(JSON.stringify(header)).toContain("👀");
    expect(JSON.stringify(header)).toContain(TASK_ID);
    // PR link present
    expect(JSON.stringify(body.blocks)).toContain(PR_URL);
  });
});

// ── 2. blocked payload ────────────────────────────────────────────────────────

describe("postTaskSlack — blocked", () => {
  it("payload includes blocked_reason section when provided", async () => {
    const mockFetch = mockFetchOk();
    await postTaskSlack({
      event: "blocked",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      prUrl: PR_URL,
      blockedReason: "missing_env_var",
      webhookUrl: WEBHOOK_URL,
    });

    const [, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    const body = JSON.parse(init.body as string) as { text: string; blocks: unknown[] };
    const header = (body.blocks as { type: string; text?: { text: string } }[]).find((b) => b.type === "header");
    expect(JSON.stringify(header)).toContain("🔴");
    expect(JSON.stringify(body.blocks)).toContain("missing_env_var");
  });

  it("no blocked_reason section when blockedReason is absent", async () => {
    const mockFetch = mockFetchOk();
    await postTaskSlack({ event: "blocked", featureId: FEATURE_ID, taskId: TASK_ID, webhookUrl: WEBHOOK_URL });

    const [, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    const body = JSON.parse(init.body as string) as { blocks: unknown[] };
    // Only 2 blocks (header + section), no extra reason section
    expect(body.blocks).toHaveLength(2);
  });
});

// ── 3. done payload ───────────────────────────────────────────────────────────

describe("postTaskSlack — done", () => {
  it("payload has ✅ header and done fallback text", async () => {
    const mockFetch = mockFetchOk();
    await postTaskSlack({ event: "done", featureId: FEATURE_ID, taskId: TASK_ID, prUrl: PR_URL, webhookUrl: WEBHOOK_URL });

    const [, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    const body = JSON.parse(init.body as string) as { text: string; blocks: unknown[] };
    expect(body.text).toContain("done");
    const header = (body.blocks as { type: string; text?: { text: string } }[]).find((b) => b.type === "header");
    expect(JSON.stringify(header)).toContain("✅");
  });
});

// ── 4. non-ok response throws ─────────────────────────────────────────────────

describe("postTaskSlack — non-ok response", () => {
  it("throws with status code when Slack returns HTTP 500", async () => {
    mockFetchFail(500);
    await expect(
      postTaskSlack({ event: "in_review", featureId: FEATURE_ID, taskId: TASK_ID, webhookUrl: WEBHOOK_URL }),
    ).rejects.toThrow("500");
  });
});

// ── 5. taskTitle in header ────────────────────────────────────────────────────

describe("postTaskSlack — taskTitle", () => {
  it("includes taskTitle in header when provided", async () => {
    const mockFetch = mockFetchOk();
    await postTaskSlack({
      event: "done",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskTitle: "Wire handoff trigger",
      prUrl: PR_URL,
      webhookUrl: WEBHOOK_URL,
    });

    const [, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    const body = JSON.parse(init.body as string) as { blocks: unknown[] };
    expect(JSON.stringify(body.blocks)).toContain("Wire handoff trigger");
  });
});

// ── 6. missing prUrl shows not available ─────────────────────────────────────

describe("postTaskSlack — missing prUrl", () => {
  it("shows _not available_ when prUrl is absent", async () => {
    const mockFetch = mockFetchOk();
    await postTaskSlack({ event: "in_review", featureId: FEATURE_ID, taskId: TASK_ID, webhookUrl: WEBHOOK_URL });

    const [, init] = mockFetch.mock.calls[0] as [string, RequestInit];
    const body = JSON.parse(init.body as string) as { blocks: unknown[] };
    expect(JSON.stringify(body.blocks)).toContain("_not available_");
  });
});

